// Portuguese and Italian inflections resolve to their dictionary forms
// (fushi/assets/transforms/pt.json / it.json, generated by
// fushi/tool/gen_romance_transforms.dart).
//
// Every table listed in manifest.json is loaded, exactly as the app does: the
// engine is language-agnostic, so the new tables share one suffix map and one
// set of POS bits with all the others. The last two groups pin that Spanish
// and English lookups are unaffected.
//
// Runs the path the app calls, Lookup::lookup() (scan_candidates ->
// text_processor -> Deinflector::deinflect -> query_raw -> filter_by_pos),
// against a real write_simple_dict dictionary (rules "*") and a real Yomitan
// import that carries parts of speech.
//
// Usage: romance_inflection_lookup_test <transforms dir>
#include <chrono>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "fushidicts/deinflector.hpp"
#include "fushidicts/importer.hpp"
#include "fushidicts/lookup.hpp"
#include "fushidicts/query.hpp"
#include "zip_fixture.hpp"

namespace {

int g_fail = 0;

void fail(const std::string& msg) {
  std::fprintf(stderr, "FAIL: %s\n", msg.c_str());
  ++g_fail;
}

std::string read_file(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  if (!in) return {};
  std::ostringstream buf;
  buf << in.rdbuf();
  return buf.str();
}

// manifest.json is a flat array of language names.
std::vector<std::string> manifest_languages(const std::string& json) {
  std::vector<std::string> out;
  size_t i = 0;
  while ((i = json.find('"', i)) != std::string::npos) {
    const size_t end = json.find('"', i + 1);
    if (end == std::string::npos) break;
    out.push_back(json.substr(i + 1, end - i - 1));
    i = end + 1;
  }
  return out;
}

std::string dump(const std::vector<LookupResult>& results) {
  std::string s;
  for (const LookupResult& r : results) {
    s += "[" + r.term.expression + " <- " + r.matched;
    for (const TransformGroup& g : r.trace) s += " /" + g.name;
    s += "] ";
  }
  return s.empty() ? "(none)" : s;
}

// The hit must cover the whole query and must have gone through a transform,
// otherwise a query that happens to be a headword itself passes trivially.
bool has_whole_deinflected_hit(const std::vector<LookupResult>& results, const std::string& query,
                               const std::string& want_expression) {
  for (const LookupResult& r : results) {
    if (r.term.expression == want_expression && r.matched == query && !r.trace.empty()) return true;
  }
  return false;
}

void expect_lemma(Lookup& lk, const std::string& query, const std::string& want, const char* what) {
  std::vector<LookupResult> results = lk.lookup(query, 32);
  if (!has_whole_deinflected_hit(results, query, want)) {
    fail(std::string(what) + ": lookup(\"" + query + "\") did not deinflect to \"" + want + "\"; got " +
         dump(results));
  }
}

void expect_no_lemma(Lookup& lk, const std::string& query, const std::string& unwanted, const char* what) {
  std::vector<LookupResult> results = lk.lookup(query, 32);
  if (has_whole_deinflected_hit(results, query, unwanted)) {
    fail(std::string(what) + ": lookup(\"" + query + "\") must NOT deinflect to \"" + unwanted + "\"; got " +
         dump(results));
  }
}

std::string term_row(const std::string& expr, const std::string& rules) {
  return "[\"" + expr + "\",\"\",\"\",\"" + rules + "\",0,[\"gloss of " + expr + "\"],0,\"\"]";
}

std::string import_yomitan(const char* label, const std::string& title, const std::vector<std::string>& rows,
                           const std::string& out_dir) {
  std::string bank = "[";
  for (size_t i = 0; i < rows.size(); i++) {
    if (i) bank += ",";
    bank += rows[i];
  }
  bank += "]";
  std::vector<fushi_test::ZipFile> files = {
      {"index.json", "{\"title\":\"" + title + "\",\"format\":3,\"revision\":\"1\"}"},
      {"term_bank_1.json", bank},
  };
  const std::string zip_path = fushi_test::write_zip(label, files);
  ImportResult r = dictionary_importer::import(zip_path, out_dir);
  if (!r.success) {
    fail(std::string("import ") + label + " failed: " + (r.errors.empty() ? "(no error)" : r.errors.front()));
    return {};
  }
  return out_dir + "/" + r.title;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <transforms dir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  const std::vector<std::string> languages = manifest_languages(read_file(dir + "/manifest.json"));
  bool has_pt = false;
  bool has_it = false;
  Deinflector d;
  for (const std::string& lang : languages) {
    const std::string json = read_file(dir + "/" + lang + ".json");
    if (json.empty()) {
      fail("manifest lists " + lang + " but " + lang + ".json cannot be read");
      continue;
    }
    d.load_transforms_json(json);
    has_pt = has_pt || lang == "pt";
    has_it = has_it || lang == "it";
  }
  if (!has_pt) fail("manifest.json does not list pt");
  if (!has_it) fail("manifest.json does not list it");
  if (g_fail) return 1;

  const std::string out_dir = fushi_test::temp_dir() + "/fushi_romance_inflection_out";
  std::filesystem::remove_all(out_dir);

  std::vector<SimpleEntry> entries;
  for (const char* w : {
           // Portuguese
           "falar", "comer", "partir", "ser", "ir", "fazer", "desfazer", "dizer", "ter", "manter", "estar", "ver",
           "pôr", "compor", "chamar", "testemunha", "animal", "homem", "português", "bonito", "lindo", "cansar",
           "conhecer", "ficar", "começar", "seguir", "dormir", "sair", "poder", "dar", "vir",
           // Italian
           "parlare", "credere", "dormire", "finire", "essere", "avere", "fare", "andare", "dire", "venire",
           "mantenere", "prendere", "comprendere", "mettere", "libro", "casa", "amico", "bello", "uomo", "anno",
           "guardare", "cercare", "mangiare", "comporre", "tradurre", "potere", "volere",
           // Spanish / English controls
           "hablar", "decir", "hacer", "walk"}) {
    entries.push_back({w, std::string("definition of ") + w});
  }
  ImportResult r = dictionary_importer::write_simple_dict("RomanceSimple", entries, out_dir);
  if (!r.success) {
    fail(r.errors.empty() ? "write_simple_dict failed" : r.errors.front());
    return 1;
  }

  {
    DictionaryQuery q;
    q.add_term_dict(out_dir + "/" + r.title);
    Lookup lk(q, d);

    // ---- A) Portuguese ------------------------------------------------------
    expect_lemma(lk, "falamos", "falar", "A1 present");
    expect_lemma(lk, "falávamos", "falar", "A2 imperfect");
    expect_lemma(lk, "falou", "falar", "A3 preterite");
    expect_lemma(lk, "falaria", "falar", "A4 conditional");
    expect_lemma(lk, "falarei", "falar", "A5 future");
    expect_lemma(lk, "falasse", "falar", "A6 imperfect subjunctive");
    expect_lemma(lk, "falando", "falar", "A7 gerund");
    expect_lemma(lk, "Falaram", "falar", "A8 capitalised (text_processor lowercases)");
    expect_lemma(lk, "comeram", "comer", "A9 -er preterite");
    expect_lemma(lk, "partiu", "partir", "A10 -ir preterite");
    expect_lemma(lk, "é", "ser", "A11 ser");
    expect_lemma(lk, "foi", "ser", "A12 foi -> ser");
    expect_lemma(lk, "foi", "ir", "A13 foi -> ir");
    expect_lemma(lk, "vou", "ir", "A14 vou -> ir");
    expect_lemma(lk, "fizeram", "fazer", "A15 fazer");
    expect_lemma(lk, "desfizeram", "desfazer", "A16 fazer compound via suffix rule");
    expect_lemma(lk, "disse", "dizer", "A17 dizer");
    expect_lemma(lk, "disse-me", "dizer", "A18 attached pronoun chained into irregular");
    expect_lemma(lk, "chama-se", "chamar", "A19 reflexive pronoun");
    expect_lemma(lk, "fazê-lo", "fazer", "A20 -lo drops the infinitive r");
    expect_lemma(lk, "pô-lo", "pôr", "A21 pô-lo -> pôr");
    expect_lemma(lk, "compô-lo", "compor", "A22 compô-lo -> compor");
    expect_lemma(lk, "tenho", "ter", "A23 ter");
    expect_lemma(lk, "mantenho", "manter", "A24 ter compound");
    expect_lemma(lk, "vejo", "ver", "A25 ver");
    expect_lemma(lk, "ponho", "pôr", "A26 pôr");
    expect_lemma(lk, "componho", "compor", "A27 pôr compound");
    expect_lemma(lk, "testemunhas", "testemunha", "A28 plural");
    expect_lemma(lk, "animais", "animal", "A29 -ais -> -al");
    expect_lemma(lk, "homens", "homem", "A30 -ns -> -m");
    expect_lemma(lk, "portugueses", "português", "A31 -eses -> -ês");
    expect_lemma(lk, "bonitas", "bonito", "A32 feminine plural adjective");
    expect_lemma(lk, "lindíssima", "lindo", "A33 superlative chained through feminine");
    expect_lemma(lk, "cansadas", "cansar", "A34 participle chained through feminine plural");
    expect_lemma(lk, "conheço", "conhecer", "A35 -cer spelling change");
    expect_lemma(lk, "fiquei", "ficar", "A36 -car preterite");
    expect_lemma(lk, "comecei", "começar", "A37 -çar preterite");
    expect_lemma(lk, "sigo", "seguir", "A38 seguir");
    expect_lemma(lk, "durmo", "dormir", "A39 dormir");
    expect_lemma(lk, "saiu", "sair", "A40 -air preterite");
    expect_lemma(lk, "pôde", "poder", "A41 poder");
    expect_lemma(lk, "deram", "dar", "A42 dar");
    expect_lemma(lk, "vieram", "vir", "A43 vir");
    expect_lemma(lk, "estiveram", "estar", "A44 estar");
    // A single letter takes whole-word rules only: the article "o" must not be
    // read as the 1sg present of "ir" through the "-o" suffix rule.
    expect_no_lemma(lk, "o", "ir", "A45 single letter skips suffix rules");

    // ---- B) Italian ---------------------------------------------------------
    expect_lemma(lk, "parliamo", "parlare", "B1 present");
    expect_lemma(lk, "parlavo", "parlare", "B2 imperfect");
    expect_lemma(lk, "parlò", "parlare", "B3 passato remoto");
    expect_lemma(lk, "parlerò", "parlare", "B4 future");
    expect_lemma(lk, "parlerei", "parlare", "B5 conditional");
    expect_lemma(lk, "parlassi", "parlare", "B6 imperfect subjunctive");
    expect_lemma(lk, "parlando", "parlare", "B7 gerund");
    expect_lemma(lk, "parlato", "parlare", "B8 participle");
    expect_lemma(lk, "credette", "credere", "B9 -ere passato remoto");
    expect_lemma(lk, "dormirono", "dormire", "B10 -ire passato remoto");
    expect_lemma(lk, "finisco", "finire", "B11 -isc- verb");
    expect_lemma(lk, "è", "essere", "B12 essere");
    expect_lemma(lk, "sono", "essere", "B13 sono");
    expect_lemma(lk, "abbiamo", "avere", "B14 avere");
    expect_lemma(lk, "faccio", "fare", "B15 fare");
    expect_lemma(lk, "fatto", "fare", "B16 fatto");
    expect_lemma(lk, "vado", "andare", "B17 andare");
    expect_lemma(lk, "dico", "dire", "B18 dire");
    expect_lemma(lk, "vengo", "venire", "B19 venire");
    expect_lemma(lk, "mantengo", "mantenere", "B20 tenere compound");
    expect_lemma(lk, "presi", "prendere", "B21 strong past");
    expect_lemma(lk, "compresero", "comprendere", "B22 strong past of a compound");
    expect_lemma(lk, "messo", "mettere", "B23 irregular participle");
    expect_lemma(lk, "libri", "libro", "B24 plural -i -> -o");
    expect_lemma(lk, "case", "casa", "B25 plural -e -> -a");
    expect_lemma(lk, "amici", "amico", "B26 plural -ci -> -co");
    expect_lemma(lk, "belle", "bello", "B27 feminine plural adjective");
    expect_lemma(lk, "uomini", "uomo", "B28 uomini -> uomo");
    expect_lemma(lk, "bellissimo", "bello", "B29 superlative");
    expect_lemma(lk, "l'anno", "anno", "B30 elided article");
    expect_lemma(lk, "l\xE2\x80\x99" "anno", "anno", "B31 elided article with typographic apostrophe");
    expect_lemma(lk, "dell'uomo", "uomo", "B32 elided preposition");
    expect_lemma(lk, "parlarmi", "parlare", "B33 infinitive with clitic");
    expect_lemma(lk, "guardalo", "guardare", "B34 imperative with clitic");
    expect_lemma(lk, "dimmi", "dire", "B35 doubled monosyllabic imperative");
    expect_lemma(lk, "fallo", "fare", "B36 fallo -> fare");
    expect_lemma(lk, "cercherò", "cercare", "B37 -care future");
    expect_lemma(lk, "mangerò", "mangiare", "B38 -giare future");
    expect_lemma(lk, "compongo", "comporre", "B39 porre compound");
    expect_lemma(lk, "tradussi", "tradurre", "B40 -durre");
    expect_lemma(lk, "può", "potere", "B41 potere");
    expect_lemma(lk, "vorrei", "volere", "B42 volere");

    // ---- C) the other languages are unaffected ------------------------------
    expect_lemma(lk, "hablamos", "hablar", "C1 Spanish still deinflects");
    expect_lemma(lk, "hablaba", "hablar", "C1b Spanish imperfect");
    expect_lemma(lk, "hablaron", "hablar", "C1c Spanish preterite");
    expect_lemma(lk, "dije", "decir", "C1d Spanish irregular preterite");
    expect_lemma(lk, "hecho", "hacer", "C1e Spanish irregular participle");
    expect_lemma(lk, "walked", "walk", "C2 English still deinflects");

    // A long line of running text must still resolve quickly with ~2700 more
    // rules in the shared suffix map.
    const auto start = std::chrono::steady_clock::now();
    for (int i = 0; i < 50; i++) {
      lk.lookup("testemunhas neste país", 32);
      lk.lookup("dell'uomo che parlavano", 32);
    }
    const double ms =
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count() / 100.0;
    std::printf("average lookup: %.3f ms\n", ms);
    if (ms > 5.0) fail("lookup got slow: " + std::to_string(ms) + " ms per call");
  }

  // ---- E) rules only chain within one language --------------------------------
  // Condition bits restart at 0 for every language and pt / it lay theirs out
  // identically, so before chains were scoped to a language a pt rule's output
  // fed it rules and back, down to the recursion limit (6.7 ms per lookup).
  for (const char* word : {"parlavano", "falávamos", "dell'uomo", "testemunhas"}) {
    const size_t n = d.deinflect(word).size();
    std::printf("deinflect(%s): %zu forms\n", word, n);
    if (n > 200) fail(std::string("E1 deinflect(\"") + word + "\") produced " + std::to_string(n) + " forms");
  }

  // ---- D) a dictionary with parts of speech still accepts these lemmas -----
  // Condition bits are allocated per language and the bare POS tags merge
  // across languages, so the filter only ever errs towards accepting. That is a
  // property of the shared engine, not of these tables; this group pins that it
  // never rejects a correct lemma.
  {
    const std::string dict_dir =
        import_yomitan("romance_pos", "RomancePos",
                       {term_row("falar", "v"), term_row("bonito", "adj"), term_row("casa", "n"),
                        term_row("parlare", "v"), term_row("libro", "n")},
                       out_dir);
    if (dict_dir.empty()) return 1;
    DictionaryQuery q;
    q.add_term_dict(dict_dir);
    Lookup lk(q, d);
    expect_lemma(lk, "falou", "falar", "D1 POS-tagged verb");
    expect_lemma(lk, "bonitas", "bonito", "D2 POS-tagged adjective");
    expect_lemma(lk, "casas", "casa", "D3 POS-tagged noun");
    expect_lemma(lk, "parlavano", "parlare", "D4 POS-tagged Italian verb");
    expect_lemma(lk, "libri", "libro", "D5 POS-tagged Italian noun");
  }

  std::filesystem::remove_all(out_dir);
  if (g_fail) {
    std::fprintf(stderr, "%d failure(s)\n", g_fail);
    return 1;
  }
  std::printf("romance_inflection_lookup_test: all passed\n");
  return 0;
}
